example.code:
slsaProvenance {
    signer = awsKms {
        region = "us-east-1"
        keyId = "arn:aws:kms:us-east-1:123456789012:key/abcd-1234"
        signingAlgorithm = "ECDSA_SHA_256"
        credentials = defaultCredentials {
        }
    }
}

slsaProvenance {
    signer = awsKms {
        region = "us-east-1"
        keyId = "alias/slsa-signer"
        signingAlgorithm = "ECDSA_SHA_256"
        credentials = defaultCredentials {
        }
    }
    assumeRole = true
    roleArn = "arn:aws:iam::123456789012:role/tc-slsa-signer"
    failBuildOnError = true
}

slsaProvenance {
    signer = awsKms {
        region = "us-east-1"
        keyId = "alias/slsa-signer"
        signingAlgorithm = "ECDSA_SHA_256"
        credentials = staticCredentials {
            accessKeyId = "AKIAIOSFODNN7EXAMPLE"
            secretAccessKey = "credentialsJSON:..."
        }
    }
    assumeRole = true
    roleArn = "arn:aws:iam::123456789012:role/tc-slsa-signer"
}
